import pathlib,numpy as np,json
D=pathlib.Path(__file__).resolve().parents[1];s=np.load(D/'reviews/upper-patch-analysis.npz');x=s['positions'];sf=s['faces'];sg=s['faceSource'];z=np.load(D/'reviews/prototype-p07-initial-selection.npz');c=np.load(D/'reviews/source-p07-excluded-components.npz');cs,ct=np.unique(c['components'],return_counts=True);small=cs[ct<1000];restore=set(c['faceIDs'][np.isin(c['components'],small)].tolist());# Negative scalar components, not a one-edge neighborhood, define each clipped hole.
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import connected_components
fn=np.cross(x[sf[:,1]]-x[sf[:,0]],x[sf[:,2]]-x[sf[:,0]]);vn=np.zeros_like(x,dtype=float)
for j in range(3):np.add.at(vn,sf[:,j],fn)
vn/=np.maximum(np.linalg.norm(vn,axis=1)[:,None],1e-20);radial=x-np.array([-.005,.690,-.005]);scalar=np.einsum('ij,ij->i',vn,radial)/np.maximum(np.linalg.norm(radial,axis=1),1e-12)
ed=np.unique(np.sort(np.vstack([sf[:,[0,1]],sf[:,[1,2]],sf[:,[2,0]]]),axis=1),axis=0);e=np.vstack([ed,ed[:,::-1]]);adj=coo_matrix((np.ones(len(e)),(e[:,0],e[:,1])),shape=(len(x),len(x))).tocsr();cnt=np.asarray(adj.sum(1)).ravel()
for _ in range(3):scalar=.5*scalar+.5*(adj@scalar)/cnt
ne=ed[(scalar[ed[:,0]]<=0)&(scalar[ed[:,1]]<=0)];sp=coo_matrix((np.ones(len(ne)),(ne[:,0],ne[:,1])),shape=(len(x),len(x))).tocsr();_,vc=connected_components(sp,directed=False);seed=np.unique(sf[list(restore)]);seed=seed[scalar[seed]<=0];comps=np.unique(vc[seed]);selected=(scalar<=0)&np.isin(vc,comps);neighbors=np.flatnonzero(np.any(selected[sf],axis=1)).tolist()
restore.update(neighbors);keep=~np.isin(z['originalFaceIDs'],list(restore));f=np.vstack([z['faces'][keep],sf[sorted(restore)]]);oi=np.r_[z['originalFaceIDs'][keep],sorted(restore)];orig=np.r_[z['isOriginal'][keep],np.ones(len(restore),bool)];group=np.r_[z['sourceFaceGroup'][keep],sg[sorted(restore)]];np.savez(D/'reviews/prototype-p07-restored-upper.npz',positions=z['positions'],faces=f,originalFaceIDs=oi,isOriginal=orig,sourceFaceGroup=group)
(D/'reviews/source-p07-local-restoration.json').write_text(json.dumps({'method':'Restore source-original fully excluded face islands enclosed by selected outer dorsal component, plus their directly adjacent clipped source faces. Main excluded lower/internal component remains removed. This restores genuine source undercuts instead of authoring fan caps.','fullyExcludedRestored':int(np.isin(c['components'],small).sum()),'neighborClippedOriginalFacesRestored':neighbors,'allRestoredSourceCombinedFaceIDs':sorted(restore)},indent=2));print('restored',len(restore))
